INSERT INTO "import_records" VALUES('events_master.csv','149',149,'{"eventID": "149", "stem": "1666", "event": "The Great Fire of London", "details": "The city was essentially medieval in its street plan, an overcrowded warren of narrow, winding, cobbled alleys. Building with wood and roofing with thatch had been prohibited for centuries, but these cheap materials continued to be used.", "wikipedia": "https://en.wikipedia.org/wiki/Great_Fire_of_London", "mnemonic": "The 1666 fire, in essense ended \"Medieval\" London, and led to important restructuring. Remember, it came 1 year after the Great Plague.", "itemDifficulty": "6", "categories": "[Catastrophes, ]", "America": "", "Europe": "1.0", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "1.0", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "", "Roman": "", "Royalty": "", "Russia": "", "Science": "", "SouthAmerica": "", "Wars": "", "World": "", "YearNum": "1666"}');
