INSERT INTO "import_records" VALUES('events_master.csv','159',159,'{"eventID": "159", "stem": "1735", "event": "Euler solves the \"Seven Bridges of Kongsberg\" problem, the start of the Graph Theory branch of mathematics.", "details": "In 1735, Euler presented a solution to the problem known as the Seven Bridges of K  nigsberg.[73] The city of K  nigsberg, Prussia was set on the Pregel River, and included two large islands that were connected to each other and the mainland by seven bridges. The problem is to decide whether it is possible to follow a path that crosses each bridge exactly once and returns to the starting point. It is not possible. This solution is considered to be the first theorem of graph theory", "wikipedia": "https://en.wikipedia.org/wiki/Seven_Bridges_of_K%C3%B6nigsberg", "mnemonic": "", "itemDifficulty": "7", "categories": "", "America": "", "Europe": "1.0", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "", "Roman": "", "Royalty": "", "Russia": "", "Science": "1.0", "SouthAmerica": "", "Wars": "", "World": "", "YearNum": "1735"}');
