INSERT INTO "legacy_csv_rows" VALUES(36,37,'305 BC ','Defeat of Seleucus at the hands of Chandragupta Maurya',' Seleucus I Nicator, one of Alexander''s Macedonian generals who in 312 BCE established the Seleucid Kingdom with its capital at Babylon, brought Persia and Bactria under his own authority, putting his eastern front facing the empire of Chandragupta. Seleucus and Chandragupta waged war until they came to an understanding with each other. Seleucus married off his daughter to Chandragupta to forge an alliance','https://en.wikipedia.org/wiki/Chandragupta_Maurya#War_and_marriage_alliance_with_Seleucus','','10','','{"America": "", "Europe": "", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "1.0", "Inventions": "", "MiddleEast": "", "prehistory": "1.0", "Religion": "", "Roman": "", "Royalty": "", "Russia": "", "Science": "", "SouthAmerica": "", "Wars": "1.0", "World": ""}',-305);
