INSERT INTO "legacy_csv_rows" VALUES(38,39,'c. 265 BC ','Start of King Ashoka s reign in India','Assuming that the Buddha died in 483 BCE  a date proposed by several scholars  Ashoka must have ascended the throne in 265 BCE','https://en.wikipedia.org/wiki/Ashoka#Date_of_ascension','','9','','{"America": "", "Europe": "", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "1.0", "Inventions": "", "MiddleEast": "", "prehistory": "1.0", "Religion": "", "Roman": "", "Royalty": "", "Russia": "", "Science": "", "SouthAmerica": "", "Wars": "", "World": ""}',-265);
INSERT INTO "legacy_csv_rows" VALUES(39,40,'261 BC ','End of the conquest of Kalinga by King Ashoka of India.','The Kalinga War (ended c.?261 BCE) was fought in ancient India between the Maurya Empire under Ashoka and the state of Kalinga, an independent feudal kingdom located on the east coast, in the present-day state of Odisha and northern parts of Andhra Pradesh. It is presumed that the battle was fought on Dhauli hills.','https://en.wikipedia.org/wiki/Kalinga_War','4 Years after ascending to the throne, Ashoka fought with the Kalingas','10','','{"America": "", "Europe": "", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "1.0", "Inventions": "", "MiddleEast": "", "prehistory": "1.0", "Religion": "", "Roman": "", "Royalty": "", "Russia": "", "Science": "", "SouthAmerica": "", "Wars": "1.0", "World": ""}',-261);
