INSERT INTO "legacy_csv_rows" VALUES(43,44,'60 BC','Roman leaders Pompey, Crassus, and Julius Caesar form the First Triumvirate.','The First Triumvirate was an informal alliance among three prominent politicians in the late Roman Republic: Gaius Julius Caesar, Gnaeus Pompeius Magnus and Marcus  Crassus.','https://en.wikipedia.org/wiki/First_Triumvirate','','7','','{"America": "", "Europe": "", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "", "Roman": "1.0", "Royalty": "", "Russia": "", "Science": "", "SouthAmerica": "", "Wars": "", "World": ""}',-60);
