INSERT INTO "legacy_csv_rows" VALUES(47,48,'48 BC','Battle of Pharsalus (Ceaser vs Pompey)',' The Battle of Pharsalus was the decisive battle of Caesar''s Civil War fought on 9 August 48 BC near Pharsalus in central Greece. Julius Caesar and his allies formed up opposite the army of the Roman Republic under the command of Pompey. Pompey had the backing of a majority of Roman senators and his army significantly outnumbered the veteran Caesarian legions  but Pompey lost fled to Egypt and was murdered there.','https://en.wikipedia.org/wiki/Battle_of_Pharsalus','','5','','{"America": "", "Europe": "", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "", "Roman": "1.0", "Royalty": "", "Russia": "", "Science": "", "SouthAmerica": "", "Wars": "1.0", "World": ""}',-48);
