INSERT INTO "legacy_csv_rows" VALUES(132,133,'1603','Death of Queen Elizabeth I.','Her reign is famous for the defeat of the Armada, and for successful raids against the Spanish. Elizabeth established an English church that helped shape a national identity and remains in place today','https://en.wikipedia.org/wiki/Elizabeth_I#Death','','5','','{"America": "", "Europe": "1.0", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "1.0", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "", "Roman": "", "Royalty": "1.0", "Russia": "", "Science": "", "SouthAmerica": "", "Wars": "", "World": ""}',1603);
