INSERT INTO "legacy_csv_rows" VALUES(137,138,'1620','Mayflower arrives in America -- Pilgrims arrived at Cape Cod, carrying passengers from England.','Mayflower arrived in New England on November 11, 1620 after a voyage of 66 days. Although the Pilgrims had originally intended to settle near the Hudson River in New York, dangerous shoals and poor winds forced the ship to seek shelter at Cape Cod.','https://en.wikipedia.org/wiki/Mayflower','The puritans wanted to "purify" England''s Anglician church. QE1 and King James (in the early 1600''s) "Persecuted" them.','3','','{"America": "", "Europe": "", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "1.0", "Roman": "", "Royalty": "", "Russia": "", "Science": "", "SouthAmerica": "", "Wars": "", "World": ""}',1620);
