INSERT INTO "legacy_csv_rows" VALUES(141,142,'1632','Galileo publishes a book claiming that the planets moved around the sun (Heliocentric), and angering the then pope.','In 1632 Galileo angered the Pope when he published a book in which he openly stated that the Earth was moving around the Sun. He was put on trial by the Inquisition in Rome, where he was found suspect of heresy, and forced to say that all of his findings were wrong','','','7','','{"America": "", "Europe": "1.0", "Asia": "", "Africa": "", "China": "", "Discovery": "1.0", "Britain": "", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "1.0", "Roman": "", "Royalty": "", "Russia": "", "Science": "1.0", "SouthAmerica": "", "Wars": "", "World": ""}',1632);
