INSERT INTO "legacy_csv_rows" VALUES(178,179,'1803','Start of the Lewis & Clark expedition, in America.','The Lewis and Clark Expedition from August 31, 1803, to September 25, 1806, also known as the Corps of Discovery Expedition, was the United States expedition to cross the newly acquired western portion of the country after the Louisiana Purchase.','https://en.wikipedia.org/wiki/Lewis_and_Clark_Expedition','It took exactly 30 years after America independence for a team to cross from the East coast to the west coast.','4','[Expeditions, Firsts, ]','{"America": "1.0", "Europe": "", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "", "Roman": "", "Royalty": "", "Russia": "", "Science": "", "SouthAmerica": "", "Wars": "", "World": ""}',1803);
