INSERT INTO "legacy_csv_rows" VALUES(301,302,'1996','Dolly the sheep becomes the first mammal to be cloned from an adult cell.','Her birth proved that specialised cells could be used to create an exact copy of the animal they came from. This knowledge changed what scientists thought was possible and opened up a lot of possibilities in biology and medicine, including the development of personalised stem cells known as iPS cells.','https://en.wikipedia.org/wiki/Dolly_(sheep)','','6','','{"America": "", "Europe": "", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "", "Roman": "", "Royalty": "", "Russia": "", "Science": "1.0", "SouthAmerica": "", "Wars": "", "World": "1.0"}',1996);
